arguments.command:
cd /workspace && cat > dev/fuzz2.py <<'PYEOF'
import sys, json
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/site')
import ctypes; ctypes.CDLL('/workspace/native/libz.so.1', mode=ctypes.RTLD_GLOBAL)
import harness; harness.setup_env()
import gen2, reference, formats, pipeline
norm = lambda o: json.dumps(o, sort_keys=True, separators=(',',':'))
bad = invalid = 0
start = int(sys.argv[1]); end = int(sys.argv[2])
for seed in range(start, end):
    request = gen2.make_request(seed)
    try:
        mine = pipeline.execute(formats.validate(json.loads(json.dumps(request))))
    except Exception as exc:
        mine = 'INVALID ' + repr(exc)
    try:
        theirs = reference.execute(request)
    except Exception as exc:
        theirs = 'INVALID'
    if isinstance(mine, str) or isinstance(theirs, str):
        invalid += 1
        continue
    if norm(mine) != norm(theirs):
        bad += 1
        print('SEED', seed, 'DIFF')
        for k in mine:
            if norm(mine[k]) != norm(theirs.get(k)):
                print(' key', k); print(norm(mine[k])[:1200]); print(norm(theirs[k])[:1200])
        print(json.dumps(request)[:4000])
print('mismatches', bad, 'invalid', invalid, 'of', end - start)
PYEOF
nohup timeout 6000 python3 dev/fuzz2.py 0 1500 > dev/fuzz2.log 2>&1 &
echo started
